question.solution:
class Student:
    count = 0
    school = 'PyMaster 学院'

    def __init__(self, name):
        self.name = name
        self.scores = []
        Student.count += 1

    def add_score(self, score):
        self.scores.append(score)
        return self

    def average(self):
        if not self.scores:
            return 0
        return round(sum(self.scores) / len(self.scores), 2)

    @classmethod
    def total(cls):
        return cls.count

a = Student('小明')
b = Student('小红')
c = Student('小刚')
a.add_score(90).add_score(80)
b.add_score(70)
print(Student.total())
print(Student.school)
for s in (a, b, c):
    print(s.name, s.average())
